import {createChatOrchestrator} from './chatOrchestrator.js';
import {rejectingWith, sessionWith} from './rejectingProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const hookCalls = async (reason: unknown) => {
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {
    hooks: {
      onError: async (_session, error) => {
        seen.push(error);
      },
    },
  });
  const rejection = await orchestrator.processMessage(sessionWith('hello')).then(
    () => 'resolved' as unknown,
    (thrown: unknown) => thrown
  );
  return {seen, rejection};
};

describe('ChatOrchestrator onError cause', () => {
  it('wraps a rejection of undefined in an Error whose cause is undefined and rethrows undefined', async () => {
    const {seen, rejection} = await hookCalls(undefined);

    expect({
      count: seen.length,
      isError: seen[0] instanceof Error,
      hasCause: seen[0] && 'cause' in seen[0],
      rejection,
    }).toEqual({
      count: 1,
      isError: true,
      hasCause: true,
      rejection: undefined,
    });
  });

  it('keeps the original object as the cause of the wrapper', async () => {
    const reason = {code: 503};

    const {seen} = await hookCalls(reason);

    expect(seen[0]?.cause).toBe(reason);
  });

  it('passes an Error to onError as the same instance', async () => {
    const reason = new Error('real');

    const {seen} = await hookCalls(reason);

    expect(seen[0]).toBe(reason);
  });
});
12:- A hook passed through `orchestrator.hooks` is forwarded to the orchestrator and fires ([validated by: forwards an orchestrator hook, so one passed through the config actually fires](../../src/config.test.ts#L19)).
13:- An engine built with no `orchestrator` key at all still processes a message, so the field is optional in fact and not only in the type ([validated by: processes a message when the config declares no orchestrator key at all](../../src/config.test.ts#L95)).
14:- A `beforeModelResponse` hook installed through config is handed the base system prompt built from `prompt`, proving the hook reaches the orchestrator and is wired into the prompt pipeline rather than only being stored on the config ([validated by: hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it](../../src/config.test.ts#L129)).
15:- The value the hook returns then replaces the system prompt the provider receives; this is exercised at the orchestrator layer because `HalEngineConfig.provider` takes a `ProviderConfig` and offers no seam to inject a recording provider through config ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L221)).
16:- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L153)).
17:- A `beforeSession` that throws reaches the caller as a rejection, and also runs `onError` with the thrown error and then `afterSession`, because the call sits inside the same `try`/`finally` as the rest of the turn. An `afterSession` hook called under this condition can infer the session never advanced past `beforeSession`: no user-input hooks ran, no model response was generated, and no tool rounds were started — a cleanup hook that allocates in `beforeSession` and frees in `afterSession` will therefore always see the allocation and the release on the same error path ([validated by: runs onError then afterSession when it throws, and still rejects to the caller](../../src/orchestration/chatOrchestrator.test.ts#L116)).
18:- `afterModelResponse` is called once per user message after the round loop exits and is passed `totalUsage` — the sum of the usage every provider call in the turn reported, not the last round alone ([validated by: sums the usage of every round, not only the last](../../src/orchestration/chatOrchestrator.test.ts#L555)).
19:- Any rejection inside the turn calls `onError` with an `Error` — passed through when the thrown value is already an `Error`, or wrapped with a readable `message` when a string or object is thrown — and then runs `afterSession` while still propagating the rejection to the caller ([validated by: calls onError with an Error carrying the thrown string and runs afterSession while rethrowing](../../src/orchestration/onErrorNonError.acceptance.test.ts#L36), [validated by: calls onError with an Error carrying a readable message when the stream rejects with a plain object](../../src/orchestration/onErrorNonError.acceptance.test.ts#L47)).
20:- The `Error` handed to `onError` for a wrapped rejection keeps the original value as its `cause`, so a hook that wants the raw value can still reach it; this holds for `undefined` too, and the caller still receives `undefined` unchanged ([validated by: wraps a rejection of undefined in an Error whose cause is undefined and rethrows undefined](../../src/orchestration/onErrorCause.test.ts#L24)). A plain object is kept by identity as that `cause` ([validated by: keeps the original object as the cause of the wrapper](../../src/orchestration/onErrorCause.test.ts#L40)).
21:- A rejection that is already an `Error` reaches `onError` as the same instance, not a wrapper ([validated by: passes an Error to onError as the same instance](../../src/orchestration/onErrorCause.test.ts#L48)).
25:- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L195)).

